const drawPlayer = () => {
  const x = playerLane * laneWidth + (laneWidth - playerSize) / 2;
  // Draw player as a rounded square with a gradient
  const grad = ctx.createLinearGradient(x, playerY, x + playerSize, playerY + playerSize);
  grad.addColorStop(0, '#00ff00');
  grad.addColorStop(1, '#006400');
  ctx.fillStyle = grad;
  const radius = 4;
  ctx.beginPath();
  ctx.moveTo(x + radius, playerY);
  ctx.lineTo(x + playerSize - radius, playerY);
  ctx.quadraticCurveTo(x + playerSize, playerY, x + playerSize, playerY + radius);
