  ctx.quadraticCurveTo(x, playerY + playerSize, x, playerY + playerSize - radius);
  ctx.lineTo(x, playerY + radius);
  ctx.quadraticCurveTo(x, playerY, x + radius, playerY);
  ctx.closePath();
  ctx.fill();
};

